#!/usr/bin/env bash
# ══════════════════════════════════════════════════════════════════
#  Physician Assistant Bot — Start server  (macOS / Linux)
#  Run:  bash start.sh
# ══════════════════════════════════════════════════════════════════
set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR"

# Activate venv if present
if [ -d ".venv" ]; then
  # shellcheck disable=SC1091
  source .venv/bin/activate
fi

# Load optional remote HTTPS settings generated by setup-remote.sh
if [ -f ".env.remote" ]; then
  # shellcheck disable=SC1091
  source .env.remote
fi

# Stop any stale listener on the app port before starting a new copy.
if command -v lsof &>/dev/null; then
  existing_pids="$(lsof -tiTCP:5001 -sTCP:LISTEN 2>/dev/null || true)"
  if [ -n "$existing_pids" ]; then
    echo "Stopping existing process(es) on port 5001..."
    kill $existing_pids 2>/dev/null || true
    for _ in 1 2 3 4 5; do
      sleep 1
      existing_pids="$(lsof -tiTCP:5001 -sTCP:LISTEN 2>/dev/null || true)"
      [ -z "$existing_pids" ] && break
    done
    if [ -n "$existing_pids" ]; then
      echo "Force-stopping stubborn process(es) on port 5001..."
      kill -9 $existing_pids 2>/dev/null || true
      sleep 1
    fi
  fi
fi

# Start Ollama in the background if not already running
if command -v ollama &>/dev/null; then
  if ! pgrep -x "ollama" > /dev/null 2>&1; then
    echo "Starting Ollama in background..."
    ollama serve &>/dev/null &
    sleep 2
  fi
fi

echo ""
echo "  Starting PhysAI..."
if [ -n "${PAB_PUBLIC_HOSTNAME:-}" ]; then
  echo "  Open https://${PAB_PUBLIC_HOSTNAME}:5001 in your browser"
else
  echo "  Open http://localhost:5001 in your browser"
fi
echo ""

# Use venv python (project requires Python 3.12; system /usr/bin/python3 is 3.9)
if [ -x ".venv/bin/python" ]; then
  .venv/bin/python main.py
else
  python3 main.py
fi
